/** Independent recipe workspace. Framing is an explicit secondary action. */
public final class FujiRecipeBook extends AppCompatActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final android.util.LruCache<String,Bitmap> covers=new android.util.LruCache<String,Bitmap>(4096){protected int sizeOf(String key,Bitmap b){return b.getAllocationByteCount()/1024+1;}};
 private LinearLayout content;private RecyclerView list;private TextView empty;private EditText search;private boolean favorites,closed,detail,editing;private int generation;
 private EditText[] activeInputs;private JSONObject activeRecord;private String[] activeCover;private ImageView activeCoverView;
 private int dp(int value){return WorkbenchNav.dp(this,value);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(0xffe4ebe7);return t;}
 private android.graphics.drawable.GradientDrawable surface(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout column(){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);return row;}
 private LinearLayout.LayoutParams space(int width,int height,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(width,height);p.topMargin=dp(top);return p;}
 private Button button(String value){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(RecipeDesign.GREEN);b.setBackground(surface(RecipeDesign.SURFACE,12));b.setBackgroundTintList(null);b.setLayoutParams(space(-1,dp(46),8));return b;}
 @Override protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=column();root.setBackgroundColor(RecipeDesign.BG);content=column();root.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setId(R.id.workbench_nav);nav.setBackgroundColor(RecipeDesign.SURFACE);root.addView(nav,new LinearLayout.LayoutParams(-1,-2));setContentView(root);MainActivity.applyInsets(getWindow(),root);WorkbenchNav.attach(this,WorkbenchNav.RECIPES);home();if(state!=null&&state.containsKey("recipe_editor"))try{edit(new JSONObject(state.getString("recipe_editor")));}catch(JSONException ignored){}String prefill=getIntent().getStringExtra("prefill_recipe");if(state==null&&prefill!=null)try{edit(new JSONObject(prefill));}catch(JSONException error){Toast.makeText(this,"无法读取原图记录",Toast.LENGTH_LONG).show();}}
 private void home(){detail=false;editing=false;activeInputs=null;activeRecord=null;activeCover=null;activeCoverView=null;generation++;content.removeAllViews();content.setPadding(dp(18),dp(12),dp(18),0);
  LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(getIntent().getBooleanExtra("choose_recipe",false)?"选择富士配方":"富士配方",27);title.setTypeface(null,android.graphics.Typeface.BOLD);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button add=button("＋ 新建配方");heading.addView(add,new LinearLayout.LayoutParams(dp(112),dp(44)));add.setOnClickListener(v->edit(null));content.addView(heading);
  TextView caption=text("记录机内色彩，让喜欢的风格随身可用",12);caption.setTextColor(0xff8da39a);content.addView(caption,space(-1,-2,8));
  Button recognize=button("从富士原图识别配方");content.addView(recognize);recognize.setOnClickListener(v->startActivityForResult(PhotoPicker.create(this,1),620));
  LinearLayout tabs=new LinearLayout(this);Button mine=button("我的配方"),star=button("收藏");tabs.addView(mine,new LinearLayout.LayoutParams(0,dp(48),1));tabs.addView(star,new LinearLayout.LayoutParams(0,dp(48),1));content.addView(tabs,space(-1,-2,12));mine.setSelected(!favorites);star.setSelected(favorites);mine.setBackground(surface(favorites?RecipeDesign.BG:0xff203c33,12));star.setBackground(surface(favorites?0xff203c33:RecipeDesign.BG,12));mine.setTextColor(favorites?0xff8da39a:RecipeDesign.GREEN);star.setTextColor(favorites?RecipeDesign.GREEN:0xff8da39a);mine.setOnClickListener(v->{favorites=false;home();});star.setOnClickListener(v->{favorites=true;home();});
  search=new EditText(this);search.setSingleLine(true);search.setTextSize(13);search.setTextColor(0xffe4ebe7);search.setHintTextColor(0xff8da39a);search.setHint("搜索名称、机型或胶片模拟");search.setBackground(surface(RecipeDesign.SURFACE,12));search.setPadding(dp(12),0,dp(12),0);content.addView(search,space(-1,dp(44),12));
  empty=text("正在读取配方…",14);empty.setGravity(Gravity.CENTER);content.addView(empty,space(-1,dp(130),18));list=new RecyclerView(this);list.setLayoutManager(new GridLayoutManager(this,2));list.setClipToPadding(false);list.setPadding(0,dp(12),0,dp(12));content.addView(list,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){load();}public void afterTextChanged(android.text.Editable e){}});load();
 }
 private void load(){if(closed||detail||editing)return;final int request=++generation;final String query=search.getText().toString();final boolean only=favorites;worker.execute(()->{List<JSONObject> records=new FujiRecipes(getApplicationContext()).list(),matches=new ArrayList<>();for(JSONObject r:records)if(FujiRecipes.matches(r,query,only))matches.add(r);runOnUiThread(()->{if(closed||detail||editing||generation!=request)return;empty.setVisibility(matches.isEmpty()?View.VISIBLE:View.GONE);empty.setText(records.isEmpty()?"还没有配方\n从原图识别，或创建你的第一份色彩记录":only?"暂无收藏配方":"没有匹配的配方");list.setAdapter(new Cards(matches));});});}
 private final class Cards extends RecyclerView.Adapter<Card>{final List<JSONObject> records;Cards(List<JSONObject> r){records=r;}public Card onCreateViewHolder(ViewGroup parent,int kind){LinearLayout tile=column();tile.setPadding(dp(6),dp(6),dp(6),dp(12));tile.setBackground(surface(RecipeDesign.SURFACE,14));RecyclerView.LayoutParams p=new RecyclerView.LayoutParams(-1,-2);p.setMargins(dp(3),dp(3),dp(3),dp(10));tile.setLayoutParams(p);ImageView image=new ImageView(FujiRecipeBook.this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setClipToOutline(true);image.setBackground(surface(0xff293b35,10));tile.addView(image,new LinearLayout.LayoutParams(-1,dp(146)));TextView title=text("",16);title.setMaxLines(2);tile.addView(title,space(-1,-2,10));TextView film=text("",12);film.setTextColor(RecipeDesign.GREEN);film.setSingleLine(true);film.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(film,space(-1,-2,6));TextView camera=text("",10);camera.setTextColor(0xff93a69f);tile.addView(camera,space(-1,-2,5));return new Card(tile,image,title,film,camera);}public void onBindViewHolder(Card card,int index){JSONObject r=records.get(index);card.title.setText(r.optString("title"));card.film.setText(r.optString("simulation","未记录模拟"));card.camera.setText((r.optBoolean("favorite")?"★  ":"")+join(r.optString("camera"),r.optString("slot")));card.itemView.setContentDescription("配方 · "+r.optString("title"));card.itemView.setOnClickListener(v->show(r));cover(card.image,r.optString("cover"));}public int getItemCount(){return records.size();}}
 private static final class Card extends RecyclerView.ViewHolder{final ImageView image;final TextView title,film,camera;Card(View root,ImageView i,TextView t,TextView f,TextView c){super(root);image=i;title=t;film=f;camera=c;}}
 private void cover(ImageView image,String source){image.setTag(source);image.setPadding(source.isEmpty()?dp(42):0,source.isEmpty()?dp(36):0,source.isEmpty()?dp(42):0,source.isEmpty()?dp(36):0);image.setScaleType(source.isEmpty()?ImageView.ScaleType.CENTER_INSIDE:ImageView.ScaleType.CENTER_CROP);image.setImageResource(R.drawable.ui_nav_recipe);image.setContentDescription(source.isEmpty()?"配方样片未添加":"配方样片");if(source.isEmpty())return;Bitmap cached=covers.get(source);if(cached!=null){image.setImageBitmap(cached);return;}worker.execute(()->{if(closed)return;Bitmap loaded=null;try{loaded=LocalMedia.decode(getApplicationContext(),Uri.parse(source),360);}catch(Exception|OutOfMemoryError ignored){}final Bitmap b=loaded;runOnUiThread(()->{if(closed){if(b!=null)b.recycle();return;}if(b!=null){covers.put(source,b);if(source.equals(image.getTag()))image.setImageBitmap(b);}});});}
 private String join(String... values){StringBuilder s=new StringBuilder();for(String v:values)if(!v.isEmpty()){if(s.length()>0)s.append(" · ");s.append(v);}return s.toString();}
 private View parameter(String key,String label,String value,boolean original){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.addView(RecipeDesign.icon(this,key,value),new LinearLayout.LayoutParams(dp(30),dp(30)));TextView name=text(label,13);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.setMarginStart(dp(12));row.addView(name,np);LinearLayout right=column();TextView setting=text(value.isEmpty()?"未记录":value,14);setting.setGravity(Gravity.END);right.addView(setting);if(original){TextView origin=text("原图识别",9);origin.setTextColor(RecipeDesign.GREEN);origin.setGravity(Gravity.END);right.addView(origin);}row.addView(right,new LinearLayout.LayoutParams(0,-2,1.25f));return row;}
 private void show(JSONObject r){detail=true;editing=false;activeInputs=null;activeRecord=null;activeCover=null;activeCoverView=null;generation++;content.removeAllViews();content.setPadding(0,0,0,0);LinearLayout top=new LinearLayout(this);Button back=button("‹ 配方");top.addView(back,new LinearLayout.LayoutParams(dp(92),dp(48)));back.setOnClickListener(v->home());TextView heading=text(r.optString("title"),18);heading.setGravity(Gravity.CENTER_VERTICAL);top.addView(heading,new LinearLayout.LayoutParams(0,dp(48),1));content.addView(top);
  ScrollView scroll=new ScrollView(this);LinearLayout body=column();body.setPadding(dp(18),0,dp(18),dp(24));scroll.addView(body);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));ImageView sample=new ImageView(this);sample.setScaleType(ImageView.ScaleType.CENTER_CROP);sample.setBackground(surface(RecipeDesign.SURFACE,14));sample.setClipToOutline(true);body.addView(sample,space(-1,dp(220),8));cover(sample,r.optString("cover"));TextView film=text(r.optString("simulation","未记录模拟"),26);film.setTextColor(RecipeDesign.GREEN);body.addView(film,space(-1,-2,18));body.addView(text(join(r.optString("camera"),r.optString("lens"),r.optString("slot")),12),space(-1,-2,8));
  JSONObject detected=r.optJSONObject("detected");for(String group:RecipeDesign.GROUPS){TextView section=text(group,14);section.setTextColor(0xff8da39a);body.addView(section,space(-1,-2,24));LinearLayout fields=column();fields.setBackground(surface(RecipeDesign.SURFACE,14));body.addView(fields,space(-1,-2,10));for(int i=0;i<FujiRecipes.KEYS.length;i++){String key=FujiRecipes.KEYS[i];if(key.equals("title")||!RecipeDesign.group(key).equals(group))continue;String value=r.optString(key);fields.addView(parameter(key,FujiRecipes.LABELS[i],value,detected!=null&&!value.isEmpty()&&value.equals(detected.optString(key))));}}
  boolean choosing=getIntent().getBooleanExtra("choose_recipe",false);Button edit=button(choosing?"带入当前作品的手动备注":"编辑配方");body.addView(edit);edit.setOnClickListener(v->{if(choosing){setResult(RESULT_OK,new Intent().putExtra("film_note",FujiRecipes.note(r)));finish();}else edit(r);});
  Button favorite=button(r.optBoolean("favorite")?"取消收藏":"收藏配方");body.addView(favorite);favorite.setOnClickListener(v->{try{r.put("favorite",!r.optBoolean("favorite"));save(r,ok->{if(ok)show(r);});}catch(JSONException ignored){}});
  Button share=button("分享参数文字");body.addView(share);share.setOnClickListener(v->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,FujiRecipes.shareText(r)),"分享配方参数")));
  Button frame=button("用此配方制作相框作品");body.addView(frame);frame.setOnClickListener(v->startActivity(new Intent(this,FrameHome.class).putExtra("pick_photo",true).putExtra("frame_style",70).putExtra("recipe_note",FujiRecipes.note(r))));
  Button delete=button("删除配方");delete.setTextColor(0xffd89587);body.addView(delete);delete.setOnClickListener(v->new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("删除此配方？").setMessage("只删除配方记录，保留照片与相框作品。").setPositiveButton("删除",(d,w)->worker.execute(()->{new FujiRecipes(getApplicationContext()).delete(r.optString("id"));runOnUiThread(()->{if(!closed)home();});})).setNegativeButton("取消",null).show());
 }
 private void edit(JSONObject existing){editing=true;detail=false;generation++;content.removeAllViews();content.setPadding(0,0,0,0);LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);Button cancel=button("‹ 配方");toolbar.addView(cancel,new LinearLayout.LayoutParams(dp(82),dp(52)));TextView title=text(existing==null?"创建富士配方":"编辑富士配方",19);toolbar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button submit=button("保存");toolbar.addView(submit,new LinearLayout.LayoutParams(dp(72),dp(52)));content.addView(toolbar);cancel.setOnClickListener(v->home());ScrollView scroll=new ScrollView(this);LinearLayout fields=column();fields.setPadding(dp(16),dp(12),dp(16),dp(20));fields.setBackgroundColor(RecipeDesign.BG);scroll.addView(fields);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));String[] cover={existing==null?"":existing.optString("cover")};ImageView sample=new ImageView(this);sample.setScaleType(ImageView.ScaleType.CENTER_CROP);sample.setBackground(surface(RecipeDesign.SURFACE,12));sample.setClipToOutline(true);fields.addView(sample,new LinearLayout.LayoutParams(-1,dp(160)));cover(sample,cover[0]);activeCover=cover;activeCoverView=sample;activeRecord=existing;Button chooseCover=button("选择配方样片");fields.addView(chooseCover);chooseCover.setOnClickListener(v->startActivityForResult(PhotoPicker.create(this,1),621));
  EditText[] inputs=new EditText[FujiRecipes.KEYS.length];activeInputs=inputs;for(String group:RecipeDesign.GROUPS){TextView heading=text(group,14);heading.setTextColor(RecipeDesign.GREEN);fields.addView(heading,space(-1,-2,24));for(int i=0;i<inputs.length;i++){final String key=FujiRecipes.KEYS[i];if(!RecipeDesign.group(key).equals(group))continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(10),0,dp(10));View symbol=RecipeDesign.icon(this,key,existing==null?"":existing.optString(key));row.addView(symbol,new LinearLayout.LayoutParams(dp(28),dp(28)));TextView label=text(FujiRecipes.LABELS[i],12);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMarginStart(dp(10));row.addView(label,lp);EditText field=new EditText(this);field.setContentDescription(FujiRecipes.LABELS[i]);field.setTextColor(0xffe4ebe7);field.setHintTextColor(0xff80958c);field.setTextSize(14);field.setBackgroundColor(android.graphics.Color.TRANSPARENT);field.setPadding(dp(8),dp(8),0,dp(8));field.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);field.setHint(key.equals("slot")?"C1–C7，可留空":"未记录");field.setText(existing==null?(key.equals("camera")?"X-E5":""):existing.optString(key));field.setSingleLine(!key.equals("notes"));field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(key.equals("notes")?1000:120)});String[] choices=RecipeDesign.choices(key);if(choices!=null){field.setFocusable(false);field.setClickable(true);field.setOnClickListener(v->{String[] values=java.util.Arrays.copyOf(choices,choices.length+2);values[choices.length]="留空 / 未记录";values[choices.length+1]="自行填写";new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(FujiRecipes.LABELS[java.util.Arrays.asList(FujiRecipes.KEYS).indexOf(key)]).setItems(values,(d,index)->{if(index<choices.length)field.setText(choices[index]);else if(index==choices.length)field.setText("");else{EditText manual=new EditText(this);manual.setText(field.getText());manual.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("填写参数").setView(manual).setPositiveButton("确定",(x,y)->field.setText(manual.getText())).setNegativeButton("取消",null).show();}}).show();});}field.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){RecipeDesign.update(symbol,s.toString());}public void afterTextChanged(android.text.Editable e){}});if(key.equals("notes")||key.equals("source")){fields.addView(row);field.setGravity(Gravity.START);fields.addView(field);}else{row.addView(field,new LinearLayout.LayoutParams(0,-2,1.6f));fields.addView(row);}View divider=new View(this);divider.setBackgroundColor(0xff25312d);fields.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));inputs[i]=field;}}
  submit.setOnClickListener(v->{if(inputs[0].getText().toString().trim().isEmpty()){inputs[0].setError("请填写名称");inputs[0].requestFocus();return;}String slot=inputs[2].getText().toString().trim().toUpperCase(Locale.ROOT);if(!slot.isEmpty()&&!slot.matches("C[1-7]")){inputs[2].setError("填写 C1–C7 或留空");inputs[2].requestFocus();return;}try{JSONObject r=existing==null?new JSONObject():new JSONObject(existing.toString());r.put("id",existing==null?UUID.randomUUID().toString():existing.getString("id"));r.put("favorite",existing!=null&&existing.optBoolean("favorite"));r.put("cover",cover[0]);for(int i=0;i<inputs.length;i++)r.put(FujiRecipes.KEYS[i],i==2?slot:inputs[i].getText().toString().trim());submit.setEnabled(false);save(r,ok->{submit.setEnabled(true);if(ok)show(r);});}catch(JSONException error){Toast.makeText(this,"无法保存配方",Toast.LENGTH_LONG).show();}});
 }
 private interface Saved{void done(boolean ok);}
 private void save(JSONObject r,Saved callback){worker.execute(()->{boolean success=true;try{new FujiRecipes(getApplicationContext()).save(r);}catch(Exception error){success=false;android.util.Log.w("fuji-recipes","Save failed",error);}final boolean ok=success;runOnUiThread(()->{if(closed)return;Toast.makeText(this,ok?"配方已保存":"保存失败，请检查存储空间",Toast.LENGTH_LONG).show();callback.done(ok);});});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=620&&request!=621)||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}if(request==621){if(activeCover!=null&&activeCoverView!=null){activeCover[0]=uri.toString();cover(activeCoverView,activeCover[0]);}return;}Toast.makeText(this,"正在读取富士原图…",Toast.LENGTH_SHORT).show();worker.execute(()->{try{String name="原图";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}PhotoDetails d=PhotoDetails.read(getApplicationContext(),uri,name);if(d.fuji.film().isEmpty()){runOnUiThread(()->{if(!closed)new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("无法识别富士参数").setMessage("请选择保留 MakerNote 的富士原始 JPEG。经处理或缺少参数的照片不会被猜测为某种胶片模拟。").setPositiveButton("知道了",null).show();});return;}JSONObject record=FujiRecipes.fromPhoto(d,name);record.put("cover",uri.toString());runOnUiThread(()->{if(closed)return;new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("识别到 "+d.fuji.film()).setMessage(join(d.camera,d.lens)+"\n\n读取了 "+d.fuji.settings.size()+" 项拍摄设置。确认后可补充配方名称和笔记。").setPositiveButton("创建我的配方",(dialog,w)->edit(record)).setNegativeButton("取消",null).show();});}catch(Exception error){android.util.Log.w("fuji-recipes","Recognition failed",error);runOnUiThread(()->{if(!closed)Toast.makeText(this,"无法读取照片，请重新选择原图",Toast.LENGTH_LONG).show();});}});}
 @Override protected void onSaveInstanceState(Bundle state){if(activeInputs!=null)try{JSONObject r=activeRecord==null?new JSONObject().put("id",UUID.randomUUID().toString()):new JSONObject(activeRecord.toString());for(int i=0;i<activeInputs.length;i++)if(activeInputs[i]!=null)r.put(FujiRecipes.KEYS[i],activeInputs[i].getText().toString());r.put("cover",activeCover==null?"":activeCover[0]);state.putString("recipe_editor",r.toString());}catch(JSONException ignored){}super.onSaveInstanceState(state);}
 @Override public void onBackPressed(){if(detail||editing)home();else super.onBackPressed();}
 @Override protected void onDestroy(){closed=true;generation++;worker.shutdown();covers.evictAll();super.onDestroy();}
}
